#pragma once
#include <optional>
#include <vector>
struct ProfileResult{std::optional<int> minimum;std::size_t comparisons;};
inline ProfileResult profile_min(std::vector<int> values){int minimum=values.front();std::size_t comparisons=1;for(std::size_t index=1;index<values.size();++index){++comparisons;if(values[index]<minimum)minimum=values[index];}return{minimum,comparisons};}

starterFiles.main.cpp:
#include <iostream>
#include <vector>
#include "candidate.hpp"
int main(){int n{};std::cin>>n;std::vector<int> values(static_cast<std::size_t>(n));for(int& value:values)std::cin>>value;const auto result=profile_min(values);std::cout<<"min=";if(result.minimum)std::cout<<*result.minimum;else std::cout<<"none";std::cout<<" comparisons="<<result.comparisons<<"\n";}

