#include <fstream>
#include <string>
#include <vector>
#include "candidate.hpp"
std::string read_review(){std::ifstream input(REVIEW_PATH);return{std::istreambuf_iterator<char>(input),{}};}
int main(){const auto empty=profile_min(std::vector<int>{});const auto single=profile_min(std::vector<int>{8});const auto values=profile_min(std::vector<int>{4,2,7});const auto review=read_review();auto has=[&](const char* value){return review.find(value)!=std::string::npos;};return !empty.minimum&&empty.comparisons==0&&single.minimum==8&&single.comparisons==0&&values.minimum==2&&values.comparisons==2&&has("finding-1: empty input dereferences front")&&has("finding-2: vector copied by value")&&has("finding-3: comparison counter starts at one")&&has("decision: request-changes")&&has("test: empty-and-singleton")&&has("profile: remove-input-copy")?0:1;}

